class Solution {
    public: vector<int> exclusiveTime(int n,vector<string>& logs){
        vector<int> answer(n),stack;
        int previous=0;
        for(string log:logs){
            int first=log.find(':'),second=log.find(':',first+1);
            int id=stoi(log.substr(0,first)),time=stoi(log.substr(second+1));
            bool start=log.substr(first+1,second-first-1)=="start";
            if(start){
                if(!stack.empty())answer[stack.back()]+=time-previous;
                stack.push_back(id);
                previous=time;
            }else{
                answer[stack.back()]+=time-previous+1;
                stack.pop_back();
                previous=time+1;
            }
        }
        return answer;
    }
};
